import Vue from "vue";
import Vuex from "vuex";
import axios from "axios";

Vue.use(Vuex);

const savedUser = localStorage.getItem("user") || "";
const savedCustomer = localStorage.getItem("customer") || "";

export default new Vuex.Store({
  state: {
    success: "",
    isLoading: false,
    user: savedUser.length ? JSON.parse(savedUser) : {},
    token: localStorage.getItem("applicationMicroToken") || "",
    company: {},
    users: [],
    interestRates: [],
    customers: [],
    accounts: [],
    currentCustomer: {},
    logs: [],
    customerTranzactions: [],
    dueInstallments: [],
    upcomingInstallments: [],
    companies: [],
    provinces: [],
    districts: [],
    customerLoans: [],
    currentCompany: {},
    updatedPassword: 0,
    smsData: "",
    companyLoans: [],
    monthllyTransactions: [],
    customerPanelData: savedCustomer.length ? JSON.parse(savedCustomer) : {},
    customerPanelLoans: [],
    customerPanelTransactions: [],
    customerPanelAmortizations: {},
    isCustomerSession: localStorage.getItem("isCustomerSession") === "true",
  },

  mutations: {
    AUTH_SUCCESS(state, user) {
      state.token = user.token;
      state.user = user;
    },

    AUTH_ERROR(state, payload) {
      state.success = payload;
    },

    AUTH_LOGOUT(state) {
      state.user = {};
      state.token = "";
    },

    LOADING_STATUS(state, payload) {
      state.isLoading = payload;
    },

    SET_COMPANY(state, company) {
      state.company = company;
    },

    SET_USERS(state, users) {
      state.users = users;
    },

    SET_INTEREST_RATES(state, interestRates) {
      state.interestRates = interestRates;
    },

    SET_CUSTOMERS(state, customers) {
      state.customers = customers;
    },

    SET_CURRENT_CUSTOMER(state, currentCustomer) {
      state.currentCustomer = currentCustomer;
    },

    SET_ACCOUNT(state, accounts) {
      state.accounts = accounts;
    },

    SET_LOGS(state, logs) {
      state.logs = logs;
    },

    SET_CUSTOMER_TRANZACTIONS(state, customerTranzactions) {
      state.customerTranzactions = customerTranzactions;
    },

    SET_DUE_INSTALLMENTS(state, dueInstallments) {
      state.dueInstallments = dueInstallments;
    },

    SET_UPCOMING_INSTALLMENTS(state, upcomingInstallments) {
      state.upcomingInstallments = upcomingInstallments;
    },

    SET_COMPANIES(state, companies) {
      state.companies = companies;
    },

    SET_PROVINCES(state, provinces) {
      state.provinces = provinces;
    },

    SET_DISTRICTS(state, districts) {
      state.districts = districts;
    },

    SET_CURRENT_COMPANY(state, currentCompany) {
      state.currentCompany = currentCompany;
    },

    SET_PASSWORD_STATUS(state, updatedPassword) {
      state.updatedPassword = updatedPassword;
    },
    SET_CUSTOMER_LOANS(state, customerLoans) {
      state.customerLoans = customerLoans;
    },
    SET_SMS_MESSAGE(state, smsData) {
      state.smsData = smsData;
    },
    SET_COMPANY_LOANS(state, companyLoans) {
      state.companyLoans = companyLoans;
    },
    SET_MONTHLY_TRANSACTIONS(state, monthllyTransactions) {
      state.monthllyTransactions = monthllyTransactions;
    },
    SET_CUSTOMER_PANEL(state, customerPanelData) {
      state.customerPanelData = customerPanelData;
    },
    SET_CUSTOMER_PANEL_LOANS(state, loans) {
      state.customerPanelLoans = loans;
    },
    SET_CUSTOMER_PANEL_TRANSACTIONS(state, transactions) {
      state.customerPanelTransactions = transactions;
    },
    SET_CUSTOMER_PANEL_AMORTIZATIONS(state, { loanId, amortizations }) {
      Vue.set(state.customerPanelAmortizations, loanId, amortizations);
    },
    SET_IS_CUSTOMER_SESSION(state, value) {
      state.isCustomerSession = value;
    },
    CUSTOMER_LOGOUT(state) {
      state.customerPanelData = {};
      state.customerPanelLoans = [];
      state.customerPanelTransactions = [];
      state.customerPanelAmortizations = {};
      state.isCustomerSession = false;
      state.token = "";
    },
  },

  actions: {
    actionDoLogin({ commit }, payload) {
      return new Promise((resolve, reject) => {
        commit("LOADING_STATUS", true);
        axios
          .post("api/login", {
            email: payload.email,
            password: payload.password,
          })
          .then((response) => {
            const data = response.data;
            if (data.success == true) {
              const user = data.result[0];
              localStorage.setItem("applicationMicroToken", user.token);
              localStorage.setItem("user", JSON.stringify(user));

              axios.defaults.headers.common[
                "Authorization"
              ] = `Bearer ${user.token}`;
              commit("SET_PASSWORD_STATUS", user.updatedPassword);
              commit("AUTH_SUCCESS", user);
              commit("AUTH_ERROR", "Autenticação bem sucedida.");
            } else {
              commit(
                "AUTH_ERROR",
                "E-mail ou password incorrecto. Tenta outra vez."
              );
            }
            commit("LOADING_STATUS", false);
            resolve(response);
          })
          .catch((err) => {
            commit("AUTH_ERROR", err.message);
            localStorage.removeItem("applicationMicroToken");
            localStorage.removeItem("user");
            commit("LOADING_STATUS", true);
            reject(err);
          });
      });
    },

    actionDoLogout({ commit }) {
      return new Promise((resolve) => {
        commit("AUTH_LOGOUT");
        localStorage.removeItem("applicationMicroToken");
        localStorage.removeItem("user");
        delete axios.defaults.headers.common["Authorization"];
        resolve();
      });
    },

    getDistricts({ commit }) {
      return new Promise((resolve, reject) => {
        commit("LOADING_STATUS", true);
        axios
          .get(`/api/districts`)
          .then((res) => {
            // console.log(res.data);
            const data = res.data;
            if (data.success == true) {
              commit("SET_DISTRICTS", data.result);
              commit("LOADING_STATUS", false);
            } else {
              commit("SET_DISTRICTS", []);
              commit("LOADING_STATUS", false);
            }
            resolve(res);
          })
          .catch((err) => {
            commit("SET_DISTRICTS", []);
            commit("LOADING_STATUS", false);
            reject(err);
          });
      });
    },

    getProvinces({ commit, dispatch }) {
      return new Promise((resolve, reject) => {
        commit("LOADING_STATUS", true);
        axios
          .get(`/api/provinces`)
          .then((res) => {
            // console.log(res.data);
            const data = res.data;
            if (data.success == true) {
              commit("SET_PROVINCES", data.result);
              dispatch("getDistricts");
              commit("LOADING_STATUS", false);
            } else {
              commit("SET_PROVINCES", []);
              commit("LOADING_STATUS", false);
            }
            resolve(res);
          })
          .catch((err) => {
            commit("SET_PROVINCES", []);
            commit("LOADING_STATUS", false);
            reject(err);
          });
      });
    },

    getAllCompanies({ commit }) {
      return new Promise((resolve, reject) => {
        commit("LOADING_STATUS", true);
        axios
          .get(`/api/company`)
          .then((res) => {
            // console.log(res.data);
            const data = res.data;
            if (data.success == true) {
              commit("SET_COMPANIES", data.result);
              commit("LOADING_STATUS", false);
            } else {
              commit("SET_COMPANIES", []);
              commit("LOADING_STATUS", false);
            }
            resolve(res);
          })
          .catch((err) => {
            commit("SET_COMPANIES", []);
            commit("LOADING_STATUS", false);
            reject(err);
          });
      });
    },

    getCompanyDetails({ commit, dispatch }, payload) {
      return new Promise((resolve, reject) => {
        commit("LOADING_STATUS", true);
        axios
          .get(`/api/company/${payload}`)
          .then((res) => {
            // console.log(res.data);
            const data = res.data;
            if (data.success == true) {
              commit("SET_COMPANY", data.result);
              if (payload === 2) {
                commit("LOADING_STATUS", false);
                return;
              }
              dispatch("getAllCustomers", payload);
              commit("LOADING_STATUS", false);
            } else {
              commit("SET_COMPANY", {});
              commit("LOADING_STATUS", false);
            }
            resolve(res);
          })
          .catch((err) => {
            console.log(err);
            commit("LOADING_STATUS", false);
            reject(err);
          });
      });
    },

    getAllRates({ commit }, payload) {
      commit("LOADING_STATUS", true);
      axios
        .get(`/api/rate/${payload}`)
        .then((res) => {
          const data = res.data;
          if (data.success == true) {
            commit("SET_INTEREST_RATES", data.result);
          } else {
            commit("SET_INTEREST_RATES", []);
          }
          commit("LOADING_STATUS", false);
        })
        .catch((err) => {
          commit("LOADING_STATUS", false);
          console.log(err);
          commit("SET_INTEREST_RATES", []);
        });
    },

    getAllCustomers({ commit, dispatch }, payload) {
      if (payload === 2) return;
      commit("LOADING_STATUS", true);
      axios
        .get(`/api/customers/${payload}`)
        .then((res) => {
          const data = res.data;
          if (data.success == true) {
            commit("SET_CUSTOMERS", data.result);
            dispatch("getAllUsers", payload);
          } else {
            commit("SET_CUSTOMERS", []);
          }
          commit("LOADING_STATUS", false);
        })
        .catch((err) => {
          commit("SET_CUSTOMERS", []);
          console.log(err);
          commit("LOADING_STATUS", false);
        });
    },

    searchCustomers({ commit }, payload) {
      commit("LOADING_STATUS", true);
      axios
        .get(`/api/searchCustomers/${payload}`)
        .then((res) => {
          const data = res.data;
          if (data.success == true) {
            commit("SET_CUSTOMERS", data.result);
          } else {
            commit("SET_CUSTOMERS", []);
          }
          commit("LOADING_STATUS", false);
        })
        .catch((err) => {
          commit("SET_CUSTOMERS", []);
          console.log(err);
          commit("LOADING_STATUS", false);
        });
    },

    getAllAccounts({ commit }, payload) {
      commit("LOADING_STATUS", true);
      return axios
        .get(`/api/accounts/${payload}`)
        .then((res) => {
          const data = res.data;
          if (data && data.success == true) {
            commit("SET_ACCOUNT", data.result);
          } else {
            commit("SET_ACCOUNT", []);
          }
          commit("LOADING_STATUS", false);
          return data;
        })
        .catch((err) => {
          commit("LOADING_STATUS", false);
          console.error("Erro ao carregar contas de pagamento:", err);
          commit("SET_ACCOUNT", []);
        });
    },

    getAllUsers({ commit, dispatch }, payload) {
      commit("LOADING_STATUS", true);
      axios
        .get(`/api/usersAll/${payload}`)
        .then((res) => {
          const data = res.data;
          if (data.success == true) {
            commit("SET_USERS", data.result);
            dispatch("getDueInstallments", payload);
          } else {
            commit("SET_USERS", []);
          }
          commit("LOADING_STATUS", false);
        })
        .catch((err) => {
          commit("LOADING_STATUS", false);
          console.log(err);
          commit("SET_USERS", []);
        });
    },

    getDueInstallments({ commit, dispatch }, payload) {
      commit("LOADING_STATUS", true);
      axios
        .get(`/api/getpastInstallments/${payload}`)
        .then((res) => {
          const data = res.data;
          if (data.success == true) {
            commit("SET_DUE_INSTALLMENTS", data.result);
            dispatch("getUpcomingInstallments", payload);
          } else {
            commit("SET_DUE_INSTALLMENTS", []);
          }
          commit("LOADING_STATUS", false);
        })
        .catch((err) => {
          commit("LOADING_STATUS", false);
          console.log(err);
          commit("SET_DUE_INSTALLMENTS", []);
        });
    },

    getUpcomingInstallments({ commit }, payload) {
      commit("LOADING_STATUS", true);
      axios
        .get(`/api/getUpcomingInstallments/${payload}`)
        .then((res) => {
          const data = res.data;
          if (data.success == true) {
            commit("SET_UPCOMING_INSTALLMENTS", data.result);
            // dispatch("getUpcomingInstallments");
          } else {
            commit("SET_UPCOMING_INSTALLMENTS", []);
          }
          commit("LOADING_STATUS", false);
        })
        .catch((err) => {
          commit("LOADING_STATUS", false);
          console.log(err);
          commit("SET_UPCOMING_INSTALLMENTS", []);
        });
    },

    addLog({ commit }, payload) {
      commit("LOADING_STATUS", true);
      axios
        .post("/api/logs", payload)
        .then((res) => {
          const data = res.data;
          if (data.success == true) {
            commit("SET_LOGS", data.result);
          } else {
            commit("SET_LOGS", []);
          }
          commit("LOADING_STATUS", false);
        })
        .catch((err) => {
          commit("LOADING_STATUS", false);
          console.log(err);
          commit("SET_LOGS", []);
        });
    },

    getCustomerLoans({ commit }, payload) {
      commit("LOADING_STATUS", true);
      axios
        .get(`/api/loan/${payload}`)
        .then((res) => {
          const data = res.data;
          if (data.success == true) {
            commit("SET_CUSTOMER_LOANS", data.result);
          } else {
            commit("SET_CUSTOMER_LOANS", []);
          }
          commit("LOADING_STATUS", false);
        })
        .catch((err) => {
          commit("LOADING_STATUS", false);
          console.log(err);
          commit("SET_CUSTOMER_LOANS", []);
        });
    },

    getCompanyLoans({ commit }, payload) {
      commit("LOADING_STATUS", true);
      axios
        .get(`/api/companyLoans/${payload}`)
        .then((res) => {
          const data = res.data;
          if (data.success == true) {
            commit("SET_COMPANY_LOANS", data.result);
          } else {
            commit("SET_COMPANY_LOANS", []);
          }
          commit("LOADING_STATUS", false);
        })
        .catch((err) => {
          commit("LOADING_STATUS", false);
          console.log(err);
          commit("SET_COMPANY_LOANS", []);
        });
    },

    getMonthllyTransactions({ commit }, payload) {
      commit("LOADING_STATUS", true);
      axios
        .get(`/api/monthllyTransactions/${payload}`)
        .then((res) => {
          const data = res.data;
          if (data.success == true) {
            commit("SET_MONTHLY_TRANSACTIONS", data.result);
          } else {
            commit("SET_MONTHLY_TRANSACTIONS", []);
          }
          commit("LOADING_STATUS", false);
        })
        .catch((err) => {
          commit("LOADING_STATUS", false);
          console.log(err);
          commit("SET_MONTHLY_TRANSACTIONS", []);
        });
    },

    // ── Portal do Cliente ──
    getCustomerPanelLoans({ commit }, accountNumber) {
      commit("LOADING_STATUS", true);
      return axios
        .get(`/api/loan/${accountNumber}`)
        .then((res) => {
          const data = res.data;
          if (data.success) {
            commit("SET_CUSTOMER_PANEL_LOANS", data.result);
          } else {
            commit("SET_CUSTOMER_PANEL_LOANS", []);
          }
          commit("LOADING_STATUS", false);
          return data;
        })
        .catch((err) => {
          commit("SET_CUSTOMER_PANEL_LOANS", []);
          commit("LOADING_STATUS", false);
          console.log(err);
        });
    },

    getCustomerPanelAmortizations({ commit }, loanId) {
      return axios
        .get(`/api/loan/amortization/${loanId}`)
        .then((res) => {
          const data = res.data;
          if (data && data.success && Array.isArray(data.result)) {
            commit("SET_CUSTOMER_PANEL_AMORTIZATIONS", {
              loanId,
              amortizations: data.result,
            });
          } else {
            commit("SET_CUSTOMER_PANEL_AMORTIZATIONS", {
              loanId,
              amortizations: [],
            });
          }
          return data;
        })
        .catch((err) => {
          commit("SET_CUSTOMER_PANEL_AMORTIZATIONS", {
            loanId,
            amortizations: [],
          });
          console.log(err);
        });
    },

    getCustomerPanelTransactions({ commit }, accountNumber) {
      commit("LOADING_STATUS", true);
      return axios
        .get(`/api/tranzaction/${accountNumber}`)
        .then((res) => {
          const data = res.data;
          if (data.success) {
            commit("SET_CUSTOMER_PANEL_TRANSACTIONS", data.result);
          } else {
            commit("SET_CUSTOMER_PANEL_TRANSACTIONS", []);
          }
          commit("LOADING_STATUS", false);
          return data;
        })
        .catch((err) => {
          commit("SET_CUSTOMER_PANEL_TRANSACTIONS", []);
          commit("LOADING_STATUS", false);
          console.log(err);
        });
    },

    customerDoLogout({ commit }) {
      return new Promise((resolve) => {
        commit("CUSTOMER_LOGOUT");
        localStorage.removeItem("applicationMicroToken");
        localStorage.removeItem("customer");
        localStorage.removeItem("isCustomerSession");
        delete axios.defaults.headers.common["Authorization"];
        resolve();
      });
    },

    sendSMSMessage({ commit }, payload) {
      commit("LOADING_STATUS", true);
      axios
        .post(`/api/sendSMS`, payload)
        .then((res) => {
          const data = res.data;
          if (data.success == true) {
            commit("SET_SMS_MESSAGE", data.message);
          } else {
            commit("SET_SMS_MESSAGE", data.message);
          }
          commit("LOADING_STATUS", false);
        })
        .catch((err) => {
          commit("LOADING_STATUS", false);
          console.log(err);
          commit("SET_SMS_MESSAGE", err.message);
        });
    },
  },

  getters: {
    isLoggedIn: (state) => !!state.token,
    isLoading: (state) => state.isLoading,
    token: (state) => state.token,
    success: (state) => state.success,
    authStatus: (state) => !!state.success,
    user: (state) => state.user,
    company: (state) => state.company,
    users: (state) => state.users,
    interestRates: (state) => state.interestRates,
    customers: (state) => state.customers,
    currentCustomer: (state) => state.currentCustomer,
    accounts: (state) => state.accounts,
    logs: (state) => state.logs,
    customerTranzactions: (state) => state.customerTranzactions,
    dueInstallments: (state) => state.dueInstallments,
    upcomingInstallments: (state) => state.upcomingInstallments,
    companies: (state) => state.companies,
    provinces: (state) => state.provinces,
    districts: (state) => state.districts,
    currentCompany: (state) => state.currentCompany,
    updatedPassword: (state) => state.updatedPassword,
    customerLoans: (state) => state.customerLoans,
    smsData: (state) => state.smsData,
    companyLoans: (state) => state.companyLoans,
    monthllyTransactions: (state) => state.monthllyTransactions,
    customerPanelData: (state) => state.customerPanelData,
    customerPanelLoans: (state) => state.customerPanelLoans,
    customerPanelTransactions: (state) => state.customerPanelTransactions,
    customerPanelAmortizations: (state) => state.customerPanelAmortizations,
    isCustomerSession: (state) => state.isCustomerSession,
  },
});
